  "images": [{ "after": "单元编号", "until": "单元编号（剧场里显示到哪一句，可省略）", "title": "这一幕的短标题", "moment": "画哪个瞬间（中文一两句：谁、在做什么、什么神情、在哪）", "who": ["画面里看得见的人物"] }],
